#include "unity.h"
#include "mock_sh1106.h"
#include "mock_platform_io.h"
#include "display.h"
#include "config.h"
#include "logo.h"
#include "display_font.h"

#include <stdbool.h>
#include <stdint.h>
#include <string.h>

static uint8_t captured_pages[8][128];
static bool page_seen[8];

static bool capture_page(sh1106_send_t send, uint8_t address, uint8_t page,
                         const uint8_t *pixels, int cmock_num_calls)
{
    (void)send;
    (void)address;
    (void)cmock_num_calls;
    if ((page < 8U) && (pixels != NULL))
    {
        memcpy(captured_pages[page], pixels, sizeof(captured_pages[page]));
        page_seen[page] = true;
    }
    return true;
}

static void expect_rendered_line(uint8_t page, const char *text)
{
    uint8_t expected[128] = {0};
    uint16_t column;

    for (column = 0U; (column < 21U) && (text[column] != '\0'); column++)
    {
        const unsigned char character = (unsigned char)text[column];
        TEST_ASSERT_TRUE((character >= 32U) && (character <= 126U));
        memcpy(&expected[column * 6U], display_font[character - 32U], 6U);
    }

    TEST_ASSERT_TRUE(page_seen[page]);
    TEST_ASSERT_EQUAL_MEMORY(expected, captured_pages[page], sizeof(expected));
}

static void render_first_dashboard(const sensors_snapshot_t *readings)
{
    /* Finish stabilization, transfer the splash, then cross its display interval. */
    display_process(UINT32_MAX, readings);
    display_process(LOGO_DISPLAY_MS, readings);

    /* The transition call sends page zero; these calls send pages one through seven. */
    display_process(LOGO_DISPLAY_MS, readings);
    display_process(LOGO_DISPLAY_MS, readings);
    display_process(LOGO_DISPLAY_MS, readings);
    display_process(LOGO_DISPLAY_MS, readings);
    display_process(LOGO_DISPLAY_MS, readings);
    display_process(LOGO_DISPLAY_MS, readings);
    display_process(LOGO_DISPLAY_MS, readings);
}

void setUp(void)
{
    memset(captured_pages, 0, sizeof(captured_pages));
    memset(page_seen, 0, sizeof(page_seen));

    platform_io_init_IgnoreAndReturn(true);
    platform_io_now_ms_IgnoreAndReturn(0U);
    platform_io_log_Ignore();
    sh1106_init_IgnoreAndReturn(true);
    sh1106_enable_IgnoreAndReturn(true);
    sh1106_page_StubWithCallback(capture_page);

    TEST_ASSERT_TRUE(display_init(0U));
}

void tearDown(void)
{
}

void test_FR_016_01(void)
{
    sensors_snapshot_t readings = {0};
    readings.climate_valid = true;
    readings.temperature_c = 23.4F;
    readings.humidity_percent = 56.7F;
    readings.acceleration_valid = true;
    readings.acceleration.x_g = 1.2F;
    readings.acceleration.y_g = -2.3F;
    readings.acceleration.z_g = 0.8F;

    render_first_dashboard(&readings);

    expect_rendered_line(0U, "Vehicle Parameters");
    expect_rendered_line(1U, "Temp:23.4 degC");
    expect_rendered_line(2U, "Humidity:56.7 %");
    expect_rendered_line(5U, "X:1.2");
    expect_rendered_line(6U, "Y:-2.3");
    expect_rendered_line(7U, "Z:0.8 g");
}

void test_FR_016_02(void)
{
    sensors_snapshot_t readings = {0};
    readings.acceleration_valid = true;
    readings.acceleration.x_g = 0.0F;
    readings.acceleration.y_g = 0.0F;
    readings.acceleration.z_g = 0.0F;

    render_first_dashboard(&readings);

    expect_rendered_line(5U, "X:0.0");
    expect_rendered_line(6U, "Y:0.0");
    expect_rendered_line(7U, "Z:0.0 g");
}
